<style>
    .finance-page { --fn-ink:#183044; --fn-muted:#718591; --fn-line:#e2eaec; --fn-green:#07856c; --fn-red:#c94b5d; --fn-blue:#3478d4; --fn-violet:#735fc6; --fn-orange:#cb7a2c; display:grid; gap:18px; color:var(--fn-ink); }
    .fn-module-nav { display:grid; grid-template-columns:repeat(5,minmax(145px,1fr)); gap:8px; overflow-x:auto; border:1px solid var(--fn-line); border-radius:15px; padding:8px; background:#fff; box-shadow:0 7px 22px rgba(24,54,67,.05); }
    .fn-module-nav>a { display:flex; min-width:145px; align-items:center; gap:9px; border:1px solid transparent; border-radius:10px; padding:10px 11px; color:#5d737d; transition:.18s ease; }.fn-module-nav>a:hover { color:#087563; border-color:#dce8e6; background:#f7fbfa; }.fn-module-nav>a.is-active { color:#087563; border-color:#cfe7e1; background:#eaf7f4; box-shadow:0 4px 12px rgba(8,117,99,.08); }.fn-module-nav>a>i { flex:0 0 auto; font-size:1.2rem; }.fn-module-nav>a>span { display:grid; line-height:1.2; }.fn-module-nav>a b { font-size:.71rem; }.fn-module-nav>a small { margin-top:3px; color:#8a9aa1; font-size:.58rem; }.fn-module-nav>a.is-active small { color:#619087; }
    .fn-hero { position:relative; display:grid; grid-template-columns:minmax(0,1.55fr) minmax(260px,.55fr); gap:28px; overflow:hidden; border-radius:22px; padding:34px 36px; color:#fff; background:linear-gradient(128deg,#123847 0%,#0b685f 58%,#0b927a 100%); box-shadow:0 18px 42px rgba(11,87,79,.2); }
    .fn-hero::after { position:absolute; right:-100px; bottom:-170px; width:390px; height:390px; border:60px solid rgba(255,255,255,.055); border-radius:50%; content:""; }
    .fn-hero-copy,.fn-hero-balance { position:relative; z-index:1; }.fn-eyebrow { display:inline-flex; align-items:center; gap:7px; color:#8be8d2; font-size:.68rem; font-weight:900; letter-spacing:.13em; text-transform:uppercase; }
    .fn-hero h1 { max-width:760px; margin:8px 0 10px; font-size:clamp(1.75rem,2.6vw,2.65rem); line-height:1.08; font-weight:850; letter-spacing:-.04em; }.fn-hero-copy>p { max-width:760px; margin:0; color:#c7dfdc; line-height:1.65; }
    .fn-hero-actions { display:flex; flex-wrap:wrap; gap:9px; margin-top:22px; }.fn-hero .btn { display:inline-flex; align-items:center; gap:7px; border-radius:10px; padding:10px 14px; font-size:.78rem; font-weight:800; }.fn-btn-light { color:#14564f; border:0; background:#fff; }.fn-btn-ghost { color:#fff; border:1px solid rgba(255,255,255,.32); background:rgba(255,255,255,.08); }.fn-btn-ghost:hover { color:#fff; background:rgba(255,255,255,.15); }
    .fn-hero-balance { align-self:center; border:1px solid rgba(255,255,255,.16); border-radius:17px; padding:20px; background:rgba(4,42,43,.22); backdrop-filter:blur(10px); }.fn-hero-balance>span { color:#9eddd1; font-size:.65rem; font-weight:850; letter-spacing:.12em; }.fn-hero-balance>strong { display:block; margin:7px 0 4px; font-size:clamp(1.5rem,2.35vw,2.15rem); font-weight:850; letter-spacing:-.04em; }.fn-hero-balance>p { margin:0 0 14px; color:#c5dcd9; font-size:.72rem; }.fn-hero-balance>div { display:flex; align-items:center; gap:7px; padding-top:12px; border-top:1px solid rgba(255,255,255,.13); color:#e2efed; font-size:.7rem; }.fn-hero-balance>div i,.fn-live i { width:7px; height:7px; border-radius:50%; background:#62e4bd; box-shadow:0 0 0 4px rgba(98,228,189,.12); }
    .fn-filter-card,.fn-panel { border:1px solid var(--fn-line); border-radius:17px; background:#fff; box-shadow:0 8px 27px rgba(24,54,67,.065); }.fn-filter-card { padding:19px; }
    .fn-section-heading,.fn-panel-heading { display:flex; align-items:center; justify-content:space-between; gap:16px; }.fn-section-heading>div:first-child,.fn-panel-heading>div:first-child { display:flex; align-items:center; gap:11px; }.fn-heading-icon { display:grid; width:38px; height:38px; flex:0 0 38px; place-items:center; border-radius:10px; color:#0a806f; background:#e7f6f3; font-size:1.15rem; }.fn-heading-icon.is-blue { color:var(--fn-blue); background:#edf4ff; }.fn-heading-icon.is-violet { color:var(--fn-violet); background:#f1effc; }.fn-heading-icon.is-green { color:var(--fn-green); background:#e8f7f3; }.fn-heading-icon.is-orange { color:var(--fn-orange); background:#fff3e7; }
    .fn-section-heading h2,.fn-panel-heading h2 { margin:0; font-size:.96rem; font-weight:850; }.fn-section-heading p,.fn-panel-heading p { margin:3px 0 0; color:var(--fn-muted); font-size:.69rem; }.fn-panel-heading small { display:block; margin-bottom:2px; color:#8da0a9; font-size:.58rem; font-weight:850; letter-spacing:.09em; }
    .fn-presets { display:flex; gap:5px; padding:4px; border-radius:9px; background:#f1f5f5; }.fn-presets button { border:0; border-radius:7px; padding:7px 10px; color:#71838c; background:transparent; font-size:.67rem; font-weight:800; }.fn-presets button.is-active { color:#087c6a; background:#fff; box-shadow:0 3px 9px rgba(25,66,72,.1); }
    .fn-filter-grid { display:grid; grid-template-columns:1.15fr repeat(5,minmax(105px,.72fr)) minmax(170px,1fr) auto; gap:10px; align-items:end; margin-top:17px; }.fn-filter-grid label,.fn-modal-grid label { display:grid; gap:5px; min-width:0; color:#5f7480; font-size:.66rem; font-weight:760; }.fn-filter-grid .form-control,.fn-filter-grid .form-select,.fn-modal-grid .form-control,.fn-modal-grid .form-select { min-height:39px; border-color:#dce6e8; border-radius:9px; color:#304d5b; font-size:.72rem; }.fn-search>div { position:relative; }.fn-search i { position:absolute; z-index:2; top:10px; left:10px; color:#82969f; }.fn-search input { padding-left:31px; }
    .fn-filter-actions { display:flex; gap:6px; }.fn-filter-actions .btn,.fn-modal .modal-footer .btn { display:inline-flex; min-height:39px; align-items:center; gap:5px; border-radius:9px; font-size:.7rem; font-weight:800; }.fn-btn-primary { color:#fff; border-color:#0a8a76; background:#0a8a76; }.fn-btn-primary:hover,.fn-btn-primary:focus { color:#fff; border-color:#087563; background:#087563; }.fn-btn-secondary { color:#60757f; border:1px solid #d9e3e5; background:#fff; }
    .fn-state { display:flex; align-items:center; gap:12px; border-radius:13px; padding:13px 16px; }.fn-state b,.fn-state small { display:block; }.fn-state small { margin-top:2px; color:var(--fn-muted); font-size:.68rem; }.fn-loading { border:1px solid #d8e9e6; background:#f1faf8; }.fn-loading>span { width:24px; height:24px; border:3px solid #c9e6e0; border-top-color:#07856c; border-radius:50%; animation:fn-spin .75s linear infinite; }.fn-error { color:#9d3444; border:1px solid #f0cbd0; background:#fff2f4; }.fn-error>i { font-size:1.5rem; }.fn-error button { margin-left:auto; border:0; color:#9d3444; background:transparent; font-size:.72rem; font-weight:850; }@keyframes fn-spin{to{transform:rotate(360deg)}}
    .fn-kpi-grid { display:grid; grid-template-columns:repeat(5,minmax(0,1fr)); gap:12px; }.fn-kpi { display:flex; min-width:0; gap:12px; align-items:flex-start; border:1px solid var(--fn-line); border-radius:15px; padding:16px; background:#fff; box-shadow:0 6px 20px rgba(25,54,66,.05); }.fn-kpi>span { display:grid; width:39px; height:39px; flex:0 0 39px; place-items:center; border-radius:11px; font-size:1.25rem; }.fn-kpi>div { min-width:0; }.fn-kpi small { color:#748791; font-size:.64rem; }.fn-kpi strong { display:block; overflow:hidden; margin-top:4px; font-size:1.12rem; font-weight:850; text-overflow:ellipsis; white-space:nowrap; }.fn-kpi p { margin:4px 0 0; color:#8999a1; font-size:.61rem; }.fn-kpi.is-income>span { color:var(--fn-green); background:#e9f7f3; }.fn-kpi.is-income strong { color:#08755f; }.fn-kpi.is-expense>span { color:var(--fn-red); background:#fff0f2; }.fn-kpi.is-expense strong { color:#b84455; }.fn-kpi.is-net>span { color:var(--fn-blue); background:#edf4ff; }.fn-kpi.is-cash>span { color:var(--fn-violet); background:#f1effc; }.fn-kpi.is-drawer>span { color:var(--fn-orange); background:#fff3e7; }
    .fn-insight-grid { display:grid; grid-template-columns:minmax(0,1.65fr) minmax(280px,.65fr); gap:18px; }.fn-panel { overflow:hidden; }.fn-panel-heading { min-height:74px; padding:16px 18px; border-bottom:1px solid #edf2f3; }.fn-live { display:flex; align-items:center; gap:7px; color:#52746e; font-size:.66rem; font-weight:750; }.fn-chart { min-height:300px; padding:8px 10px 0; }
    .fn-method-list { display:grid; gap:0; max-height:316px; overflow:auto; padding:7px 17px; }.fn-method-row { display:grid; grid-template-columns:38px minmax(0,1fr) auto; align-items:center; gap:10px; padding:11px 0; border-bottom:1px solid #eef2f3; }.fn-method-row:last-child { border-bottom:0; }.fn-method-row>span { display:grid; width:34px; height:34px; place-items:center; border-radius:9px; color:#6956b6; background:#f1effb; }.fn-method-copy b,.fn-method-copy small { display:block; }.fn-method-copy b { color:#304a58; font-size:.72rem; }.fn-method-copy small { margin-top:2px; color:#84959d; font-size:.61rem; }.fn-method-value { text-align:right; }.fn-method-value strong,.fn-method-value small { display:block; }.fn-method-value strong { font-size:.72rem; }.fn-method-value strong.is-negative { color:var(--fn-red); }.fn-method-value strong.is-positive { color:var(--fn-green); }.fn-method-value small { margin-top:2px; color:#8798a0; font-size:.6rem; }
    .fn-panel-heading>a { color:#087c6a; font-size:.69rem; font-weight:800; }.fn-drawer-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:11px; padding:16px 18px 18px; }.fn-drawer-card { display:grid; gap:13px; border:1px solid #e0e9e9; border-radius:13px; padding:14px; background:linear-gradient(180deg,#fff,#f9fbfb); }.fn-drawer-card>div { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; }.fn-drawer-card b,.fn-drawer-card small { display:block; }.fn-drawer-card b { color:#284652; font-size:.75rem; }.fn-drawer-card small { margin-top:3px; color:#81939b; font-size:.62rem; }.fn-drawer-card>div>span { padding:4px 7px; border-radius:999px; color:#08775f; background:#e7f7f2; font-size:.57rem; font-weight:850; }.fn-drawer-metrics { display:grid!important; grid-template-columns:1fr 1fr; gap:8px!important; }.fn-drawer-metrics span { display:grid; padding:9px; border-radius:9px; background:#f0f5f5; }.fn-drawer-metrics small { margin:0; }.fn-drawer-metrics strong { margin-top:3px; color:#183b45; font-size:.8rem; }
    .fn-row-count { border-radius:999px; padding:6px 9px; color:#60747e; background:#f0f4f5; font-size:.63rem; font-weight:800; }.fn-table { min-width:1160px; margin:0; }.fn-table thead th { border-bottom:1px solid #dfe7e9; padding:11px 13px; color:#627984; background:#f7f9f9; font-size:.61rem; font-weight:850; letter-spacing:.045em; text-transform:uppercase; white-space:nowrap; }.fn-table tbody td { border-color:#edf1f2; padding:11px 13px; color:#3f5965; font-size:.7rem; vertical-align:middle; }.fn-reference b,.fn-reference small,.fn-category b,.fn-category small { display:block; }.fn-reference b,.fn-category b { color:#274552; font-size:.7rem; }.fn-reference small,.fn-category small { max-width:250px; overflow:hidden; margin-top:3px; color:#81949d; font-size:.61rem; text-overflow:ellipsis; white-space:nowrap; }.fn-source,.fn-method-badge,.fn-status { display:inline-flex; align-items:center; gap:5px; border-radius:999px; padding:5px 8px; white-space:nowrap; font-size:.6rem; font-weight:800; }.fn-source { color:#376ea7; background:#ecf4fd; }.fn-source.is-manual { color:#6d58b8; background:#f0eefb; }.fn-source.is-cashier { color:#a06323; background:#fff3e5; }.fn-source.is-return { color:#b44555; background:#fff0f2; }.fn-method-badge { color:#546d77; background:#eef3f4; }.fn-amount { font-variant-numeric:tabular-nums; font-weight:850; white-space:nowrap; }.fn-amount.is-income { color:#08765f; }.fn-amount.is-expense { color:#bd4657; }.fn-voided td { opacity:.62; }.fn-voided .fn-amount { text-decoration:line-through; }.fn-status { color:#a23a4a; background:#fff0f2; }.fn-row-action { display:grid; width:30px; height:30px; place-items:center; border:1px solid #ead8db; border-radius:8px; color:#ad4051; background:#fff8f9; }.fn-ledger-note { display:flex; align-items:flex-start; gap:8px; border-top:1px solid #edf2f3; padding:12px 16px; color:#758990; background:#fbfcfc; font-size:.63rem; line-height:1.55; }.fn-ledger-note i { color:#087c6a; font-size:1rem; }
    .fn-source.is-system { color:#347267; background:#eaf5f2; }
    .fn-empty { grid-column:1/-1; padding:28px!important; color:#82959d!important; text-align:center; font-size:.7rem!important; }.fn-modal { overflow:hidden; border:0; border-radius:17px; }.fn-modal .modal-header { align-items:flex-start; padding:19px 21px; color:#fff; border:0; background:linear-gradient(125deg,#143b49,#087a69); }.fn-modal .modal-header h5 { margin:3px 0; font-weight:850; }.fn-modal .modal-header p { margin:0; color:#c5dcda; font-size:.68rem; }.fn-modal-kicker { color:#82dfcc; font-size:.6rem; font-weight:900; letter-spacing:.12em; }.fn-modal .btn-close { filter:brightness(0) invert(1); }.fn-modal .modal-body { padding:20px; background:#fafcfc; }.fn-modal-grid { display:grid; grid-template-columns:1fr 1fr; gap:13px; }.fn-modal-grid label>span b { color:#c64a5b; }.fn-modal-wide { grid-column:1/-1; }.fn-money-input { position:relative; }.fn-money-input>b { position:absolute; z-index:2; top:10px; left:11px; color:#6d838c; }.fn-money-input input { padding-left:35px; }.fn-cash-notice { display:flex; gap:10px; align-items:flex-start; margin-top:14px; border:1px solid #cae7e1; border-radius:10px; padding:11px 12px; color:#3d6862; background:#edf9f6; font-size:.66rem; line-height:1.5; }.fn-cash-notice>i { color:#07856c; font-size:1.15rem; }.fn-modal .modal-footer { border-top:1px solid #e7eded; padding:13px 20px; }
    .fn-monthly-heading-tools { display:flex; align-items:center; justify-content:flex-end; gap:10px; }.fn-monthly-filter { display:grid; grid-template-columns:auto auto; gap:2px 7px; align-items:center; color:#617780; font-size:.61rem; font-weight:800; }.fn-monthly-filter>span:first-child { white-space:nowrap; }.fn-monthly-filter>small { grid-column:2; margin:0; color:#91a0a6; font-size:.54rem; font-weight:700; letter-spacing:0; }.fn-monthly-filter-control { position:relative; display:flex; align-items:center; }.fn-monthly-filter-control>i { position:absolute; z-index:2; left:9px; color:#799098; font-size:.9rem; pointer-events:none; }.fn-monthly-filter-control .form-control { width:150px; min-height:36px; border-color:#dce6e8; border-radius:9px 0 0 9px; padding-left:29px; color:#304d5b; background:#fff; font-size:.68rem; }.fn-monthly-filter-control button { display:grid; width:34px; height:36px; place-items:center; border:1px solid #dce6e8; border-left:0; border-radius:0 9px 9px 0; color:#73868e; background:#f8fafa; }.fn-monthly-filter-control button:disabled { color:#bdc8cc; cursor:not-allowed; }.fn-account-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:13px; padding:17px 18px; background:#fbfcfc; }.fn-account-card { position:relative; display:grid; grid-template-columns:auto minmax(0,1fr); gap:13px; align-items:start; overflow:hidden; border:1px solid #dce8e8; border-radius:14px; padding:17px; background:#fff; }.fn-account-card::after { position:absolute; right:-30px; bottom:-48px; width:115px; height:115px; border:21px solid rgba(10,133,108,.055); border-radius:50%; content:""; }.fn-account-icon { display:grid; width:42px; height:42px; place-items:center; border-radius:12px; color:#087b68; background:#e8f7f3; font-size:1.3rem; }.fn-account-card.is-profit .fn-account-icon { color:#5274bd; background:#edf3ff; }.fn-account-card.is-net_profit .fn-account-icon { color:#9d641f; background:#fff3e4; }.fn-account-copy { min-width:0; }.fn-account-copy small { color:#8a9ba2; font-size:.57rem; font-weight:850; letter-spacing:.07em; }.fn-account-copy h3 { margin:2px 0 6px; color:#294854; font-size:.78rem; font-weight:850; }.fn-account-copy strong { display:block; color:#08755f; font-size:1.35rem; font-weight:900; letter-spacing:-.03em; }.fn-account-card.is-profit .fn-account-copy strong { color:#4565aa; }.fn-account-card.is-net_profit .fn-account-copy strong { color:#915b19; }.fn-account-copy p { margin:4px 0 0; color:#81939b; font-size:.62rem; }.fn-account-change { position:relative; z-index:1; grid-column:1/-1; display:inline-flex; width:max-content; align-items:center; gap:4px; border-radius:999px; padding:5px 8px; color:#667b84; background:#f0f4f5; font-size:.58rem; font-weight:800; white-space:nowrap; }.fn-account-change.is-up { color:#08745e; background:#e8f7f2; }.fn-account-change.is-down { color:#b54354; background:#fff0f2; }.fn-monthly-table { min-width:1160px; }.fn-monthly-table tbody tr.is-current { background:#f1faf7; }.fn-month-label b,.fn-month-label small { display:block; }.fn-month-label b { color:#294854; font-size:.7rem; }.fn-month-label small { margin-top:2px; color:#8799a0; font-size:.59rem; }.fn-margin { color:#536d78; font-weight:850; white-space:nowrap; }
    .fn-filter-grid--overview { grid-template-columns:minmax(180px,1.3fr) repeat(2,minmax(150px,1fr)) auto; }.fn-filter-grid--monthly { grid-template-columns:minmax(210px,1fr) minmax(190px,1fr) auto; }.fn-filter-grid--cash-flow { grid-template-columns:minmax(170px,1.15fr) repeat(4,minmax(135px,1fr)) auto; }.fn-filter-grid--cashier { grid-template-columns:minmax(230px,1fr) auto; }.fn-kpi-grid--four { grid-template-columns:repeat(4,minmax(0,1fr)); }.fn-kpi-grid--three { grid-template-columns:repeat(3,minmax(0,1fr)); }
    .fn-feature-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; padding:18px; }.fn-feature-grid>a { display:grid; grid-template-columns:auto minmax(0,1fr) auto; align-items:center; gap:13px; border:1px solid #e0e9e9; border-radius:13px; padding:16px; color:#31505c; background:linear-gradient(180deg,#fff,#fafcfc); transition:.18s ease; }.fn-feature-grid>a:hover { border-color:#bcdcd5; color:#087563; transform:translateY(-1px); box-shadow:0 8px 20px rgba(24,54,67,.07); }.fn-feature-grid>a>span { display:grid; width:42px; height:42px; place-items:center; border-radius:11px; font-size:1.25rem; }.fn-feature-grid>a>span.is-green { color:var(--fn-green); background:#e8f7f3; }.fn-feature-grid>a>span.is-blue { color:var(--fn-blue); background:#edf4ff; }.fn-feature-grid>a>span.is-orange { color:var(--fn-orange); background:#fff3e7; }.fn-feature-grid>a>span.is-violet { color:var(--fn-violet); background:#f1effc; }.fn-feature-grid h3 { margin:0; font-size:.78rem; font-weight:850; }.fn-feature-grid p { margin:4px 0 0; color:#7c8f97; font-size:.63rem; line-height:1.45; }.fn-feature-grid>a>i { color:#91a2a8; }
    @media(max-width:1380px){.fn-filter-grid{grid-template-columns:repeat(4,1fr)}.fn-filter-grid--monthly{grid-template-columns:repeat(3,1fr)}.fn-filter-grid--cash-flow{grid-template-columns:repeat(3,1fr)}.fn-filter-grid--cashier{grid-template-columns:minmax(230px,1fr) auto}.fn-filter-actions{justify-content:flex-end}.fn-kpi-grid{grid-template-columns:repeat(3,1fr)}}
    @media(max-width:920px){.fn-hero{grid-template-columns:1fr}.fn-insight-grid,.fn-account-grid,.fn-feature-grid{grid-template-columns:1fr}.fn-drawer-grid{grid-template-columns:repeat(2,1fr)}.fn-section-heading,.fn-panel-heading{align-items:flex-start}.fn-monthly-heading-tools{align-items:flex-end;flex-direction:column}.fn-filter-grid{grid-template-columns:repeat(2,1fr)}}
    @media(max-width:590px){.fn-module-nav{grid-template-columns:repeat(5,145px)}.fn-hero{padding:26px 22px}.fn-section-heading,.fn-panel-heading{flex-direction:column}.fn-presets{width:100%;overflow:auto}.fn-monthly-heading-tools{width:100%;align-items:stretch}.fn-monthly-filter{grid-template-columns:auto 1fr}.fn-monthly-filter-control .form-control{width:100%}.fn-row-count{width:max-content}.fn-filter-grid,.fn-kpi-grid,.fn-drawer-grid,.fn-modal-grid{grid-template-columns:1fr}.fn-account-card{grid-template-columns:auto minmax(0,1fr)}.fn-account-change{grid-column:1/-1;width:max-content}.fn-modal-wide{grid-column:auto}.fn-filter-actions{width:100%}.fn-filter-actions .btn{flex:1}}
</style>
